func mustSampleExtractor(ex SampleExtractor, err error) SampleExtractor {
	if err != nil {
		panic(err)
	}
	return ex
}

func appendLabel(l labels.Labels, name, value string) labels.Labels {
	b := labels.NewBuilder(l)
	b.Set(name, value)
	return b.Labels()
}

func (p *stubExtractor) ForStream(_ labels.Labels) StreamSampleExtractor {
	return p.sp
}

func (p *stubStreamExtractor) BaseLabels() LabelsResult {
	builder := NewBaseLabelsBuilder().ForLabels(labels.FromStrings("foo", "bar"), 0)
	return builder.LabelsResult()
}

func (p *stubStreamExtractor) Process(
	_ int64,
	_ []byte,
	structuredMetadata labels.Labels,
) (ExtractedSample, bool) {
	builder := NewBaseLabelsBuilder().ForLabels(labels.FromStrings("foo", "bar"), 0)
	builder.Add(StructuredMetadataLabel, structuredMetadata)
	return ExtractedSample{Value: 1.0, Labels: builder.LabelsResult()}, true
}

func (p *stubStreamExtractor) ProcessString(
	_ int64,
	_ string,
	structuredMetadata labels.Labels,
) (ExtractedSample, bool) {
	builder := NewBaseLabelsBuilder().ForLabels(labels.FromStrings("foo", "bar"), 0)
	builder.Add(StructuredMetadataLabel, structuredMetadata)
	return ExtractedSample{Value: 1.0, Labels: builder.LabelsResult()}, true
}

func appendLabels(base labels.Labels, l labels.Labels) labels.Labels {
	b := labels.NewBuilder(base)

	l.Range(func(l labels.Label) {
		b.Set(l.Name, l.Value)
	})

	return b.Labels()
}

func newPipelineFilter(start, end int64, lbls, structuredMetadata labels.Labels, filter string) PipelineFilter {
	var stages []Stage
	var matchers []*labels.Matcher
	lbls.Range(func(l labels.Label) {
		m := labels.MustNewMatcher(labels.MatchEqual, l.Name, l.Value)
		matchers = append(matchers, m)
	})

	structuredMetadata.Range(func(l labels.Label) {
		s := NewStringLabelFilter(labels.MustNewMatcher(labels.MatchEqual, l.Name, l.Value))
		stages = append(stages, s)
	})

	stages = append(stages, mustFilter(NewFilter(filter, LineMatchEqual)).ToStage())

	return PipelineFilter{start, end, matchers, NewPipeline(stages)}
}

func mustFilter(f Filterer, err error) Filterer {
	if err != nil {
		panic(err)
	}
	return f
}

func mustStage(s Stage, err error) Stage {
	if err != nil {
		panic(err)
	}
	return s
}

