	}
	renameError := func() Stage {
		f, err := NewLabelsFormatter([]LabelFmt{NewRenameLabelFmt("e", logqlmodel.ErrorLabel)})
		require.NoError(t, err)
		return f
	}

	for _, tc := range []struct {
		name        string
		stages      Stages
		postFilters []LabelFilterer
